import{c as t,Q as o,j as i,m as n}from"./chunks/framework.BPKcPtvA.js";const f=JSON.parse('{"title":"Notification log","description":"View the history of all dispatched webhook notifications.","frontmatter":{"title":"Notification log","description":"View the history of all dispatched webhook notifications."},"headers":[],"relativePath":"src/content/docs/admin/notifications.md","filePath":"src/content/docs/admin/notifications.md"}'),a={name:"src/content/docs/admin/notifications.md"};function r(l,e,s,d,h,c){return o(),i("div",null,[...e[0]||(e[0]=[n('<p>The notification log at <code>/admin/notifications</code> shows every webhook dispatch attempt - what was sent, to which webhook, and whether it succeeded.</p><h2 id="reading-the-log" tabindex="-1">Reading the log <a class="header-anchor" href="#reading-the-log" aria-label="Permalink to &quot;Reading the log&quot;">​</a></h2><p>Each row shows:</p><ul><li><strong>Time</strong> - <code>HH:MM:SS</code> when the notification was dispatched</li><li><strong>Webhook</strong> - the name of the destination channel</li><li><strong>Event</strong> - the audit event that triggered the notification</li><li><strong>Status</strong> - <code>Sent</code> (green) or <code>Failed</code> (red)</li><li><strong>Error</strong> - the error message if delivery failed (hover for full text)</li></ul><h2 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h2><p>Use the <strong>Sent / Failed</strong> filter chips to narrow the log. Type in the search box to filter by webhook name, event, or error text.</p><h2 id="bell-icon" tabindex="-1">Bell icon <a class="header-anchor" href="#bell-icon" aria-label="Permalink to &quot;Bell icon&quot;">​</a></h2><p>The bell icon in the topbar shows a red dot when there are new notifications since you last viewed the log. Clicking the bell opens a dropdown with the 8 most recent notifications and a &quot;View all&quot; link. The dot clears when you open the dropdown.</p><h2 id="debugging-failed-deliveries" tabindex="-1">Debugging failed deliveries <a class="header-anchor" href="#debugging-failed-deliveries" aria-label="Permalink to &quot;Debugging failed deliveries&quot;">​</a></h2><p>If a webhook shows <code>Failed</code>:</p><ol><li>Check the error column for the HTTP status code or error message.</li><li>Go to <strong>Webhooks</strong> and use the test button to re-send a test notification and see the live error.</li><li>Common causes: <ul><li>Wrong URL or token</li><li>Bot not added to Telegram chat</li><li>ntfy topic not accessible</li><li>SMTP not configured (for email webhooks)</li></ul></li></ol>',11)])])}const p=t(a,[["render",r]]);export{f as __pageData,p as default};
